action.code:
if (open_list_.empty()) {
    return nullptr;
}

auto min_it = std::min_element(open_list_.begin(), open_list_.end(),
    [](const RouteModel::Node* a, const RouteModel::Node* b) {
        return (a->g_value + a->h_value) < (b->g_value + b->h_value);
    });

RouteModel::Node* result = *min_it;
open_list_.erase(min_it);
return result;

